using Unity.Burst;
using Unity.Mathematics;

namespace ZE.MechBattle.Projectiles
{
    public static class HighAngleTrajectoryPartitioningLogic
    {
        // generated by Deepseek, fixed by Qwen

        /// <summary>
        /// Выдаёт три доли времени полёта (t1, t2) для разбиения параболы на участки:
        /// начальный (крутой подъём) / центральный (пологая вершина) / финальный (крутое падение).
        /// Опирается на v0 из калькулятора наводки и полное время полёта.
        /// </summary>
        /// <param name="v0">начальная скорость (вектор, не нормализованный)</param>
        /// <param name="g">положительное g (например 9.81)</param>
        /// <param name="tTotal">полное время полёта до цели</param>
        /// <param name="slopeThreshold">порог |dy/dx|, ниже которого участок считается пологим (напр. 0.2 ≈ 11°)</param>
        /// <param name="fallbackT1">доля на случай, если порог не достигается</param>
        /// <param name="fallbackT2">доля на случай, если порог не достигается</param>
        /// <returns>(t1, t2) — доли в [0,1], t1 &lt;= t2</returns>
        [BurstCompile]
        public static float2 CalculatePartitions(
        float3 v0, float g, float tTotal,
        float slopeThreshold = 0.2f,
        float fallbackT1 = 0.25f,
        float fallbackT2 = 0.75f)
        {
            if (tTotal <= 1e-5f)
                return float2.zero;

            float vHoriz = math.length(new float2(v0.x, v0.z));

            // Почти вертикальный выстрел
            if (vHoriz < 1e-4f)
                return GetSafeFallback(fallbackT1, fallbackT2);

            // t1 - это начало пологого участка (меньшее время), t2 - конец (большее время)
            float t1 = (v0.y - slopeThreshold * vHoriz) / g;
            float t2 = (v0.y + slopeThreshold * vHoriz) / g;

            // Нормализуем в диапазон [0, 1]
            t1 = math.clamp(t1, 0f, tTotal) / tTotal;
            t2 = math.clamp(t2, 0f, tTotal) / tTotal;

            // Если пологий участок не выделяется (t1 >= t2) — используем fallback.
            if (t1 >= t2)
                return GetSafeFallback(fallbackT1, fallbackT2);

            return new float2(t1, t2);
        }

        [BurstCompile]
        private static float2 GetSafeFallback(float f1, float f2)
        {
            float safeT1 = math.saturate(math.min(f1, f2));
            float safeT2 = math.saturate(math.max(f1, f2));
            return new float2(safeT1, safeT2);
        }

    }
}
